package com.bank.treasury;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class PermutationsDemo {

    private static final Logger log = Logger.getLogger(PermutationsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TransferOrderPlanner planner = new TransferOrderPlanner();

        String[] transfers = {"TXF-1", "TXF-2", "TXF-3"};

        List<List<String>> orders = planner.allOrders(transfers);
        log.info(() -> "Total orderings: " + orders.size());  // 6 = 3!
        orders.forEach(o -> log.info(() -> "  order: " + o));
    }
}

