class TransferOrderPlanner {

    private static final Logger log = Logger.getLogger(TransferOrderPlanner.class.getName());

    java.util.List<java.util.List<String>> allOrders(String[] transfers) {
        java.util.List<java.util.List<String>> result = new java.util.ArrayList<>();
        boolean[] used = new boolean[transfers.length];
        backtrack(transfers, used, new java.util.ArrayList<>(), result);
        return result;
    }

    private void backtrack(String[] transfers, boolean[] used,
                           java.util.List<String> path,
                           java.util.List<java.util.List<String>> result) {
        if (path.size() == transfers.length) {   // full arrangement → record copy
            result.add(new java.util.ArrayList<>(path));
            return;
        }
        for (int i = 0; i < transfers.length; i++) {
            if (used[i]) continue;                // skip already-placed transfers
            used[i] = true;
            path.add(transfers[i]);
            backtrack(transfers, used, path, result);
            path.remove(path.size() - 1);         // undo
            used[i] = false;                      // free it for other branches
        }
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
